package org.apache.commons.math.optimization.univariate;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Comparator;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.exception.ConvergenceException;
import org.apache.commons.math.exception.MathIllegalStateException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.optimization.ConvergenceChecker;
import org.apache.commons.math.optimization.GoalType;
import org.apache.commons.math.random.RandomGenerator;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math3.optim.univariate.GoalType;
import org.apache.commons.math3.optim.univariate.UnivariateRealFunction;
import org.apache.commons.math3.optim.univariate.UnivariateRealPointValuePair;
import org.apache.commons.math3.random.JDKRandomGenerator;
import org.apache.commons.math3.random.RandomGenerator;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.invocation.InvocationOnMock;
import org.mockito.stubbing.Answer;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyDouble;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class MultiStartUnivariateRealOptimizer_optimize_TriageGen1Test {

    private BaseUnivariateRealOptimizer<UnivariateRealFunction> mockOptimizer;
    private RandomGenerator mockGenerator;
    private MultiStartUnivariateRealOptimizer optimizer;

    @Before
    public void setUp() {
        mockOptimizer = mock(BaseUnivariateRealOptimizer.class);
        mockGenerator = mock(RandomGenerator.class);
        // Using 1 start to keep test predictable
        optimizer = new MultiStartUnivariateRealOptimizer(mockOptimizer, 1, mockGenerator);
    }

    @Test
    public void testOptimize_Minimization() throws FunctionEvaluationException {
        // Arrange
        UnivariateRealFunction f = new UnivariateRealFunction() {
            @Override
            public double value(double x) {
                return Math.pow(x - 2.0, 2);
            }
        };
        GoalType goal = GoalType.MINIMIZE;
        double min = 0.0;
        double max = 4.0;

        UnivariateRealPointValuePair expectedResult = new AbstractUnivariateRealPointValuePair(2.0, 0.0);

        when(mockOptimizer.optimize(eq(f), eq(goal), eq(min), eq(max), anyDouble()))
            .thenReturn(expectedResult);

        // Act
        UnivariateRealPointValuePair result = optimizer.optimize(f, goal, min, max);

        // Assert
        assertNotNull(result);
        assertEquals(2.0, result.getPoint(), 1e-10);
        assertEquals(0.0, result.getValue(), 1e-10);
        verify(mockOptimizer).optimize(eq(f), eq(goal), eq(min), eq(max), anyDouble());
    }

    @Test
    public void testOptimize_Maximization() throws FunctionEvaluationException {
        // Arrange
        UnivariateRealFunction f = x -> Math.sin(x);
        GoalType goal = GoalType.MAXIMIZE;
        double min = 0.0;
        double max = Math.PI;

        UnivariateRealPointValuePair expectedResult = new AbstractUnivariateRealPointValuePair(Math.PI / 2.0, 1.0);

        when(mockOptimizer.optimize(eq(f), eq(goal), eq(min), eq(max), anyDouble()))
            .thenReturn(expectedResult);

        // Act
        UnivariateRealPointValuePair result = optimizer.optimize(f, goal, min, max);

        // Assert
        assertNotNull(result);
        assertEquals(Math.PI / 2.0, result.getPoint(), 1e-10);
        assertEquals(1.0, result.getValue(), 1e-10);
    }

    @Test(expected = FunctionEvaluationException.class)
    public void testOptimize_ThrowsException() throws FunctionEvaluationException {
        // Arrange
        UnivariateRealFunction f = x -> {
            throw new FunctionEvaluationException(new RuntimeException("Eval error"));
        };
        GoalType goal = GoalType.MINIMIZE;
        double min = 0.0;
        double max = 1.0;

        // We don't mock the optimizer here so the real call propagates the exception if it were real, 
        // but since we are testing the wrapper/delegation:
        when(mockOptimizer.optimize(any(), any(), anyDouble(), anyDouble(), anyDouble()))
            .thenThrow(new FunctionEvaluationException(new RuntimeException("Eval error")));

        // Act
        optimizer.optimize(f, goal, min, max);
    }

    /**
     * Helper class to mock the return value of UnivariateRealPointValuePair
     */
    private static class AbstractUnivariateRealPointValuePair implements UnivariateRealPointValuePair {
        private final double point;
        private final double value;

        public AbstractUnivariateRealPointValuePair(double point, double value) {
            this.point = point;
            this.value = value;
        }

        @Override
        public double getPoint() { return point; }

        @Override
        public double getValue() { return value; }
    }
}
